const body = $input.first().json.body;
const alert = body.alerts[0];

return {
  alertname: alert.labels.alertname,
  severity: alert.labels.severity,
  namespace: alert.labels.namespace,
  pod: alert.labels.pod,
  status: alert.status,
  summary: alert.annotations.summary,
  description: alert.annotations.description,
  startsAt: alert.startsAt,
  notification_reason: body.notification_reason
};

const rawOutput = $input.first().json.output;

let report;
try {
  const clean = rawOutput
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();
  report = JSON.parse(clean);
} catch(e) {
  report = null;
}

// ─── EMAIL ────────────────────────────────────────────────────
let subject, htmlBody;

if (report) {
  const i = report.incident;
  const rc = report.root_cause;
  const rec = report.recommendation;
  const inv = report.investigation;

  subject = report.email?.subject || `[${i.severity.toUpperCase()}] ${i.alertname} - ${i.namespace}/${i.pod}`;

  htmlBody = `
<div style="font-family: Arial, sans-serif; max-width: 680px; margin: 0 auto; background: #f5f5f5; padding: 20px;">

  <div style="background: ${i.severity === 'critical' ? '#dc2626' : '#d97706'}; padding: 20px 24px; border-radius: 8px 8px 0 0;">
    <h1 style="color: white; margin: 0; font-size: 18px;">
      🚨 Kubernetes Alert: ${i.alertname}
    </h1>
    <p style="color: rgba(255,255,255,0.85); margin: 6px 0 0; font-size: 13px;">
      ${i.severity.toUpperCase()} · ${i.namespace}/${i.pod} · ${new Date(i.started_at).toUTCString()}
    </p>
  </div>

  <div style="background: white; padding: 24px; border-radius: 0 0 8px 8px; border: 1px solid #e5e7eb;">

    <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
      <tr style="background: #f9fafb;">
        <td style="padding: 8px 12px; font-size: 12px; color: #6b7280; font-weight: bold; width: 140px;">ALERT</td>
        <td style="padding: 8px 12px; font-size: 13px; color: #111827;">${i.alertname}</td>
      </tr>
      <tr>
        <td style="padding: 8px 12px; font-size: 12px; color: #6b7280; font-weight: bold;">SEVERITY</td>
        <td style="padding: 8px 12px; font-size: 13px; color: ${i.severity === 'critical' ? '#dc2626' : '#d97706'}; font-weight: bold;">${i.severity.toUpperCase()}</td>
      </tr>
      <tr style="background: #f9fafb;">
        <td style="padding: 8px 12px; font-size: 12px; color: #6b7280; font-weight: bold;">NAMESPACE</td>
        <td style="padding: 8px 12px; font-size: 13px; font-family: monospace; color: #111827;">${i.namespace}</td>
      </tr>
      <tr>
        <td style="padding: 8px 12px; font-size: 12px; color: #6b7280; font-weight: bold;">POD</td>
        <td style="padding: 8px 12px; font-size: 13px; font-family: monospace; color: #111827;">${i.pod}</td>
      </tr>
      <tr style="background: #f9fafb;">
        <td style="padding: 8px 12px; font-size: 12px; color: #6b7280; font-weight: bold;">STATUS</td>
        <td style="padding: 8px 12px; font-size: 13px; color: #111827;">${i.status}</td>
      </tr>
    </table>

    <h2 style="font-size: 14px; color: #374151; border-left: 3px solid #dc2626; padding-left: 10px; margin: 20px 0 10px;">Root Cause</h2>
    <p style="font-size: 13px; color: #374151; margin: 0 0 6px;"><strong>${rc.summary}</strong></p>
    <p style="font-size: 13px; color: #6b7280; margin: 0 0 6px;">${rc.technical_detail}</p>
    <p style="font-size: 12px; color: #9ca3af; margin: 0;"><em>Blast radius: ${rc.blast_radius}</em></p>

    <h2 style="font-size: 14px; color: #374151; border-left: 3px solid #2563eb; padding-left: 10px; margin: 20px 0 10px;">Recommendation</h2>
    <p style="font-size: 13px; color: #374151; margin: 0 0 6px;">⚡ <strong>Immediate:</strong> ${rec.immediate_action}</p>
    <p style="font-size: 13px; color: #374151; margin: 0;">🔧 <strong>Long-term:</strong> ${rec.long_term_fix}</p>

    <h2 style="font-size: 14px; color: #374151; border-left: 3px solid #059669; padding-left: 10px; margin: 20px 0 10px;">Commands Executed</h2>
    <div style="background: #1e1e2e; border-radius: 6px; padding: 12px 16px;">
      ${inv.commands_executed.map(cmd =>
        `<p style="font-family: monospace; font-size: 12px; color: #a5f3d4; margin: 4px 0;">$ ${cmd}</p>`
      ).join('')}
    </div>

    <h2 style="font-size: 14px; color: #374151; border-left: 3px solid #7c3aed; padding-left: 10px; margin: 20px 0 10px;">Findings</h2>
    <p style="font-size: 13px; color: #374151; margin: 0;">${inv.findings}</p>

  </div>

  <p style="text-align: center; font-size: 11px; color: #9ca3af; margin-top: 16px;">
    Automated by K8s AI Agent · n8n · ${new Date().toUTCString()}
  </p>

</div>`;

} else {
  subject = "K8s Alert - Investigation Report";
  htmlBody = `<pre style="font-family: monospace; font-size: 12px;">${rawOutput}</pre>`;
}

// ─── RETURN ───────────────────────────────────────────────────
return {
  subject,
  htmlBody
};
